#include "vtf_block_decode.h"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("texture path required");std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>b((std::istreambuf_iterator<char>(f)),{});auto layout=readVtfTextureLayoutCandidate(b);auto image=decodeVtfMipCandidate(b,0);if(image.rgba.size()!=size_t(image.width)*image.height*4)throw std::runtime_error("pixel size mismatch");std::ofstream output(argv[2],std::ios::binary);output.write(reinterpret_cast<const char*>(image.rgba.data()),image.rgba.size());output.close();if(!output)throw std::runtime_error("iris pixel export failed");auto bad=b;bad.resize(80);bool rejected=false;try{readVtfTextureLayoutCandidate(bad);}catch(...){rejected=true;}if(!rejected)throw std::runtime_error("truncated resource accepted");std::cout<<"VTF73 texture passed width="<<image.width<<" height="<<image.height<<" mips="<<layout.mips.size()<<" truncated_resource_rejected=1\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
